import {FieldValidatorFn} from '../types/field-validator-fn';

// Regex generated by claude
// this checks if the string only has numbers from 0 to 9. '-', '+', '.', ',' or any alphabetic letter will fail.
export const intValidator: FieldValidatorFn = (value: string): string | null => /^\d+$/.test(value) ? null : 'Muss eine positive Ganzzahl ohne Vorzeichen sein.';